function trackedStocks(productId){return stocks.filter(s=>s.active!==false&&s.automaticDeduction&&s.linkedMenuItemId===productId)}
function reservedUnits(productId,exceptOrderId=""){return orders.filter(o=>o.id!==exceptOrderId).reduce((sum,o)=>sum+(o.items||[]).filter(i=>i.id===productId).reduce((n,i)=>n+(Number(i.quantity)||0),0),0)}
