function activeBundleRules(){const day=today();return(catalog.bundleRules||[]).filter(rule=>rule.active!==false&&(!rule.startDate||day>=rule.startDate)&&(!rule.endDate||day<=rule.endDate)&&catalog.items.some(item=>item.id===rule.triggerProductId)&&catalog.items.some(item=>item.id===rule.rewardProductId))}
