function renderProducts(){const q=el.productSearch.value.trim().toLocaleLowerCase('tr-TR'),usage=new Map();for(const sale of sales.filter(s=>s.recordType==='sale'))for(const item of sale.items||[])usage.set(item.id,(usage.get(item.id)||0)+(Number(item.quantity)||0));const cats=[...catalog.categories].sort((a,b)=>(a.order||0)-(b.order||0)),merchantSpecialIds=new Set(cats.filter(c=>String(c.name||'').trim().toLocaleLowerCase('tr-TR')==='esnaf özel').map(c=>c.id));el.categoryTabs.innerHTML=`<button class="${category==='all'?'active':''}" data-category="all">Tümü</button>`+cats.map(c=>`<button class="${category===c.id?'active':''}" data-category="${esc(c.id)}">${esc(c.name)}</button>`).join('');const items=catalog.items.filter(i=>i.available!==false&&(category==='all'?!merchantSpecialIds.has(i.categoryId):i.categoryId===category)&&String(i.name).toLocaleLowerCase('tr-TR').includes(q)).sort((a,b)=>(usage.get(b.id)||0)-(usage.get(a.id)||0)||(a.order||0)-(b.order||0));el.productGrid.innerHTML=items.map(i=>{const state=productStockState(i.id);return`<button class="product stock-${state.status}" data-product="${esc(i.id)}" ${state.status==='empty'?'aria-disabled="true" tabindex="-1"':''}><strong>${esc(i.name)}</strong><span>${money(i.price)}</span></button>`}).join('');el.productEmpty.hidden=items.length>0}
async function addProduct(id){if(!selectedKey){show('Önce bir masa veya Adisyon seçin.');return false}const p=catalog.items.find(i=>i.id===id);if(!p||busy)return false;const o=orderFor(selectedKey),items=[...(o?.items||[])];items.push({id:p.id,lineId:newId(),name:p.name,unitPrice:Number(p.price)||0,quantity:1,complimentary:false,addedAtMs:Date.now()});const next=applyBundleRules(items,o?.suppressedBundleRuleIds),problem=stockProblem(next,o?.id||"");if(problem){show(problem);return false}return await saveOrder(o,next)}
